const SAVE_KEY='sag-frontier-save-v05',memoryStore={};
const storage={get(k){try{return window.localStorage.getItem(k)}catch{return memoryStore[k]??null}},set(k,v){try{window.localStorage.setItem(k,v)}catch{memoryStore[k]=String(v)}}};
const defaults=()=>({version:7,language:'de',credits:250,cores:0,skillPoints:0,best:0,weapons:{laser:{unlocked:true,level:1},rail:{unlocked:false,level:0},rocket:{unlocked:false,level:0},plasma:{unlocked:false,level:0},arc:{unlocked:false,level:0},flak:{unlocked:false,level:0}},ships:{vanguard:{unlocked:true,level:1},interceptor:{unlocked:false,level:0},bastion:{unlocked:false,level:0},specter:{unlocked:false,level:0},carrier:{unlocked:false,level:0}},modules:{targeting:{unlocked:true,level:1},salvage:{unlocked:false,level:0},capacitor:{unlocked:false,level:0},armor:{unlocked:false,level:0},magnet:{unlocked:false,level:0},amplifier:{unlocked:false,level:0}},skills:{hull:0,damage:0,cooldown:0,salvage:0,crit:0,speed:0},loadout:{ship:'vanguard',primary:'laser',secondary:null,module:'targeting'},stats:{runs:0,kills:0,bosses:0,creditsEarned:0,skillPointsEarned:0}});
let save=loadSave();
function loadSave(){try{const x=JSON.parse(storage.get(SAVE_KEY)||'null');return normalize(x)}catch{return defaults()}}
function normalize(x){const d=defaults();if(!x||typeof x!=='object')return d;const out={...d,...x};out.weapons={...d.weapons,...(x.weapons||{})};out.ships={...d.ships,...(x.ships||{})};out.modules={...d.modules,...(x.modules||{})};out.skills={...d.skills,...(x.skills||{})};out.loadout={...d.loadout,...(x.loadout||{})};out.stats={...d.stats,...(x.stats||{})};if(!['de','en'].includes(out.language))out.language='de';for(const id of Object.keys(d.weapons)){out.weapons[id]={...d.weapons[id],...(out.weapons[id]||{})};out.weapons[id].level=Math.max(out.weapons[id].unlocked?1:0,Math.min(5,Number(out.weapons[id].level)||0))}for(const id of Object.keys(d.ships)){out.ships[id]={...d.ships[id],...(out.ships[id]||{})};out.ships[id].level=Math.max(out.ships[id].unlocked?1:0,Math.min(5,Number(out.ships[id].level)||0))}for(const id of Object.keys(d.modules)){out.modules[id]={...d.modules[id],...(out.modules[id]||{})};out.modules[id].level=Math.max(out.modules[id].unlocked?1:0,Math.min(5,Number(out.modules[id].level)||0))}for(const id of Object.keys(d.skills))out.skills[id]=Math.max(0,Math.min(id==='crit'||id==='speed'?2:3,Math.floor(Number(out.skills[id])||0)));if(!out.ships[out.loadout.ship]?.unlocked)out.loadout.ship='vanguard';if(!out.weapons[out.loadout.primary]?.unlocked)out.loadout.primary='laser';if(out.loadout.secondary&&!out.weapons[out.loadout.secondary]?.unlocked)out.loadout.secondary=null;if(out.loadout.secondary===out.loadout.primary)out.loadout.secondary=null;if(out.loadout.module&&!out.modules[out.loadout.module]?.unlocked)out.loadout.module='targeting';out.credits=Math.max(0,Math.floor(Number(out.credits)||0));out.cores=Math.max(0,Math.floor(Number(out.cores)||0));out.best=Math.max(0,Math.floor(Number(out.best)||0));out.skillPoints=Math.max(0,Math.floor(Number(out.skillPoints)||0));return out}
function persist(){storage.set(SAVE_KEY,JSON.stringify(save));renderHangar()}

