const skillTree={hull:{max:3,cost:1,branch:'survival'},damage:{max:3,cost:1,branch:'combat'},cooldown:{max:3,cost:1,branch:'systems'},salvage:{max:3,cost:1,branch:'systems'},crit:{max:2,cost:2,requires:{id:'damage',rank:2},branch:'combat'},speed:{max:2,cost:2,requires:{id:'hull',rank:2},branch:'survival'}};

function canPay(cost){return save.credits>=cost.c&&save.cores>=cost.k}function pay(cost){save.credits-=cost.c;save.cores-=cost.k}
function levelCost(kind,id,level){const src=kind==='weapon'?weapons[id]:kind==='ship'?ships[id]:modules[id];return{c:src.upgrade[level-1]||0,k:level>=3?1:0}}
function buySkill(id){const node=skillTree[id],rank=save.skills[id]||0;if(!node||rank>=node.max||save.skillPoints<node.cost)return;if(node.requires&&(save.skills[node.requires.id]||0)<node.requires.rank)return;save.skillPoints-=node.cost;save.skills[id]=rank+1;persist()}
function unlock(kind,id){const src=kind==='weapon'?weapons[id]:kind==='ship'?ships[id]:modules[id],cost=src.unlock;if(!canPay(cost))return;pay(cost);const bucket=kind==='weapon'?save.weapons:kind==='ship'?save.ships:save.modules;bucket[id]={unlocked:true,level:1};persist()}
function upgradePermanent(kind,id){const bucket=kind==='weapon'?save.weapons:kind==='ship'?save.ships:save.modules,entry=bucket[id];if(!entry.unlocked||entry.level>=5)return;const cost=levelCost(kind,id,entry.level);if(!canPay(cost))return;pay(cost);entry.level++;persist()}
function equipWeapon(id,slot){if(!save.weapons[id].unlocked)return;if(slot==='secondary'&&save.loadout.primary===id)save.loadout.primary=save.loadout.secondary||'laser';if(slot==='primary'&&save.loadout.secondary===id)save.loadout.secondary=save.loadout.primary;save.loadout[slot]=id;if(save.loadout.primary===save.loadout.secondary)save.loadout.secondary=null;persist()}
function equipShip(id){if(save.ships[id].unlocked){save.loadout.ship=id;persist()}}function equipModule(id){if(save.modules[id].unlocked){save.loadout.module=id;persist()}}

function renderHangar(){const q=t();document.documentElement.lang=save.language;document.title=q.title;$('langDe').classList.toggle('active',save.language==='de');$('langEn').classList.toggle('active',save.language==='en');$('hangarTitle').textContent=q.hangar;$('hangarSubtitle').textContent=q.hangarSub;$('creditsValue').textContent=save.credits;$('creditsLabel').textContent=q.credits;$('coresValue').textContent=save.cores;$('coresLabel').textContent=q.cores;$('bestValue').textContent=save.best;$('hangarBestLabel').textContent=q.best;$('tabDeployment').textContent=q.deployment;$('tabWeapons').textContent=q.weapons;$('tabShips').textContent=q.ships;$('tabModules').textContent=q.modules;$('tabSkills').textContent=q.skills;$('tabData').textContent=q.data;$('skillPointsValue').textContent=save.skillPoints;$('skillPointsLabel').textContent=q.skillPoints;$('shipSlotLabel').textContent=q.ship;$('primarySlotLabel').textContent=q.primary;$('secondarySlotLabel').textContent=q.secondary;$('moduleSlotLabel').textContent=q.module;$('shipSlot').textContent=q.shipNames[save.loadout.ship];$('primarySlot').textContent=q.weaponNames[save.loadout.primary];$('secondarySlot').textContent=save.loadout.secondary?q.weaponNames[save.loadout.secondary]:q.none;$('moduleSlot').textContent=save.loadout.module?q.moduleNames[save.loadout.module]:q.none;$('economyNote').textContent=q.economy;$('startRunBtn').textContent=q.start;$('exportTitle').textContent=q.exportTitle;$('exportText').textContent=q.exportText;$('refreshExportBtn').textContent=q.refresh;$('importTitle').textContent=q.importTitle;$('importText').textContent=q.importText;$('importBtn').textContent=q.import;$('resetSaveBtn').textContent=q.reset;$('progressHint').textContent=q.progress;$('careerStats').textContent=q.career(save.stats);$('exportArea').value=btoa(unescape(encodeURIComponent(JSON.stringify(save))));
 const icon=$('shipIcon');icon.className='ship-icon '+(save.loadout.ship==='vanguard'?'':save.loadout.ship);
 $('weaponGrid').innerHTML='';for(const id of Object.keys(weapons))$('weaponGrid').appendChild(weaponCard(id));
 $('shipGrid').innerHTML='';for(const id of Object.keys(ships))$('shipGrid').appendChild(shipCard(id));
 $('moduleGrid').innerHTML='';for(const id of Object.keys(modules))$('moduleGrid').appendChild(moduleCard(id));$('skillGrid').innerHTML='';for(const id of Object.keys(skillTree))$('skillGrid').appendChild(skillCard(id));
}
function priceText(cost){return `${cost.c} ${t().credits}${cost.k?` + ${cost.k} ${t().cores}`:''}`}
function pips(level){return '◆'.repeat(level)+'◇'.repeat(Math.max(0,5-level))}
function weaponCard(id){const q=t(),entry=save.weapons[id],d=document.createElement('article');d.className='card '+(!entry.unlocked?'locked ':'')+((save.loadout.primary===id||save.loadout.secondary===id)?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('weapon',id,entry.level):weapons[id].unlock;d.innerHTML=`<h3>${q.weaponNames[id]}</h3><div class="level-pips">${pips(entry.level)}</div><p>${q.weaponDesc[id]}</p><div class="tag-row"><span class="tag strong">${q.strong}: ${q.strongTexts[id]}</span><span class="tag weak">${q.weak}: ${q.weakTexts[id]}</span></div><div class="muted">${entry.unlocked?(entry.level>=5?q.max:`${q.cost}: ${priceText(cost)}`):`${q.cost}: ${priceText(cost)}`}</div>`;const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked){a.append(btn(q.buy,()=>unlock('weapon',id),!canPay(cost),'gold'))}else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('weapon',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.primary===id?q.equippedPrimary:q.equipPrimary,()=>equipWeapon(id,'primary'),save.loadout.primary===id));a.append(btn(save.loadout.secondary===id?q.equippedSecondary:q.equipSecondary,()=>equipWeapon(id,'secondary'),save.loadout.secondary===id))}d.append(a);return d}
function shipCard(id){const q=t(),entry=save.ships[id],d=document.createElement('article');d.className='card '+(!entry.unlocked?'locked ':'')+(save.loadout.ship===id?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('ship',id,entry.level):ships[id].unlock,s=ships[id].stats;d.innerHTML=`<h3>${q.shipNames[id]}</h3><div class="level-pips">${pips(entry.level)}</div><p>${q.shipDesc[id]}</p><div class="tag-row"><span class="tag">HP ${s.hp}</span><span class="tag">SPD ${s.speed}</span><span class="tag">SHD ${s.shield}</span></div><div class="muted">${entry.unlocked?(entry.level>=5?q.max:`${q.cost}: ${priceText(cost)}`):`${q.cost}: ${priceText(cost)}`}</div>`;const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked)a.append(btn(q.buy,()=>unlock('ship',id),!canPay(cost),'gold'));else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('ship',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.ship===id?q.equipped:q.equip,()=>equipShip(id),save.loadout.ship===id))}d.append(a);return d}
function moduleCard(id){const q=t(),entry=save.modules[id],d=document.createElement('article');d.className='card '+(!entry.unlocked?'locked ':'')+(save.loadout.module===id?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('module',id,entry.level):modules[id].unlock;d.innerHTML=`<h3>${q.moduleNames[id]}</h3><div class="level-pips">${pips(entry.level)}</div><p>${q.moduleDesc[id]}</p><div class="muted">${entry.unlocked?(entry.level>=5?q.max:`${q.cost}: ${priceText(cost)}`):`${q.cost}: ${priceText(cost)}`}</div>`;const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked)a.append(btn(q.buy,()=>unlock('module',id),!canPay(cost),'gold'));else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('module',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.module===id?q.equipped:q.equip,()=>equipModule(id),save.loadout.module===id))}d.append(a);return d}
function skillCard(id){const q=t(),node=skillTree[id],rank=save.skills[id]||0,locked=node.requires&&(save.skills[node.requires.id]||0)<node.requires.rank,d=document.createElement('article');d.className='card skill-node '+node.branch+(locked?' locked':'')+(rank>=node.max?' selected':'');const req=locked?'<div class="muted">'+q.requires+': '+q.skillNames[node.requires.id]+' '+node.requires.rank+'</div>':'';d.innerHTML='<h3>'+q.skillNames[id]+'</h3><div class="level-pips">'+'◆'.repeat(rank)+'◇'.repeat(node.max-rank)+'</div><p>'+q.skillDesc[id]+'</p>'+req+'<div class="muted">'+q.rank+' '+rank+' / '+node.max+' · '+node.cost+' '+(node.cost===1?q.skillPoint:q.skillPoints)+'</div>';const a=document.createElement('div');a.className='card-actions';a.append(btn(rank>=node.max?q.max:q.learn,()=>buySkill(id),rank>=node.max||locked||save.skillPoints<node.cost,'gold'));d.append(a);return d}
